"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/** Props for a word or short phrase that melts into the next one when `text` changes. */
export type TextMorphProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  /** The word or short phrase to show. Changing it runs the morph. Keep it on one line. */
  text: string;
};

// Critically damped: a shared letter slides to its new place and stops.
const SLIDE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const ARRIVE: Transition = { duration: 0.25, ease: [0.165, 0.84, 0.44, 1] };
const LEAVE: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };

const GONE = { opacity: 0, filter: "blur(0.25rem)" };
const HERE = { opacity: 1, filter: "blur(0rem)" };

/**
 * Pairs each letter with the same letter in the next text: the first "e" with
 * the first "e", the second with the second. A paired letter keeps its element.
 */
function keyedLetters(text: string) {
  const seen = new Map<string, number>();
  return [...text].map((char) => {
    const nth = seen.get(char) ?? 0;
    seen.set(char, nth + 1);
    return { char, key: `${char}-${nth}` };
  });
}

/**
 * Swaps one word or short phrase for another by melting the letters together.
 * Letters both texts share slide to their new place; the others blur out and
 * in. Screen readers get the plain text once, and with reduced motion the new
 * text replaces the old one at once.
 */
export function TextMorph({ text, className, ...spanProps }: TextMorphProps) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return (
      <span {...spanProps} className={className}>
        {text}
      </span>
    );
  }

  return (
    <span {...spanProps} className={cn("relative inline-flex whitespace-nowrap", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        <AnimatePresence mode="popLayout" initial={false}>
          {keyedLetters(text).map(({ char, key }) => (
            <motion.span
              key={key}
              layout="position"
              initial={GONE}
              animate={{ ...HERE, transition: ARRIVE }}
              exit={{ ...GONE, transition: LEAVE }}
              transition={{ layout: SLIDE }}
              // A space must keep its width, or two words would run together.
              className="inline-block whitespace-pre"
            >
              {char}
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </span>
  );
}
